def main():
    out = []
    out.append({'section': 'engine_gate', 'engine_sha': sha,
                'pin': PIN, 'gate': 'PASS'})
    vC = ns['vC']
    vO = ns['vO']

    # (a) K0832 battery: the UNION of the kit-16 2,098 literal triples plus
    #     the kit-17 literals registered in this kit.
    battery_lits = json.loads(BATTERY_TRIPLES_JSON)
    battery = []
    bad_bat = 0
    for (x, z2, R2) in battery_lits:
        cf = v(x, z2, R2)
        cn = vC(x, z2, R2)
        od = vO(x, z2, R2)
        ok = (cf == cn == od)
        if not ok:
            bad_bat += 1
        battery.append({'x': x, 'z': z2, 'R': R2, 'closed': cf,
                        'vC': cn, 'vO': od, 'match': ok})
    out.append({'section': 'k0832_battery', 'literals': len(battery),
                'all_match': bad_bat == 0, 'bad': bad_bat,
                'rows': battery})

    # (b) the 30 binding candidate rows (kit-16 frozen future constants,
    #     verbatim frozen texts; zero rows skipped: the kit-16 registration
    #     was machine-checked at build to contain no self/earlier overlaps).
    #     Rule-v2 stack shadows are registered for EVERY 2-token seat with
    #     co >= 2m (the standing rule-v2 enumeration, confirmed six times):
    #     the m19/m20/m21/m22 stick, NEW and one-past seats included.
    K14_BINDING = json.loads(K17_BINDING_JSON)

    def emit_row(secname, rlabel, extra, m, z):
        R = m + z + 1
        smax = max(m + 38, z + 2)
        return row_record_x0(secname, rlabel, extra, R, z, m, m, smax)

    for r in K14_BINDING:
        m = r['m']
        z = r['z']
        if r['kind'] == 'frontier':
            secname = 'frontier_m%d_z%d_row_record' % (m, z)
            label = ('registered_frontier_record_m%d_z%d_K1268_%s_datum_candidate'
                     % (m, z, r['nth']))
            registered_by = ('kit-16 frozen output section future_slice_registration_constants '
                             '(commit f997daca), the registered %s parity datum candidate; '
                             'FIRST-EVER m>48 row; the frozen prediction text is byte-verbatim'
                             % r['nth'])
        else:
            secname = 'ladder_m%d_z%d_row_record' % (m, z)
            label = 'registered_kit16future_item%d_%s' % (r['item'], r['kind'])
            registered_by = ('kit-16 frozen output section future_slice_registration_constants '
                             'item %d of the 34 registered kit-17 constants (commit f997daca); '
                             'the frozen prediction text is byte-verbatim; zero rows '
                             'skipped: the kit-17 registration was machine-checked at '
                             'build to contain no self/earlier overlaps'
                             % r['item'])
        extra = {'co_token_%d_allowed' % m: True,
                 's_domain': '{%d..%d}' % (m, max(m + 38, z + 2)), 'arity_max': 3,
                 'style': 'x0 published residual-band style',
                 'registered_by': registered_by,
                 'candidate': r['cand'],
                 'seat_kind': r['kind'],
                 'expect_seats': r['seats'],
                 'expect_dead_seat': r['dead_seat'],
                 'binding': True}
        if r.get('seat_ud'):
            extra['seat_ud'] = r['seat_ud']
        if r.get('stack_candidates'):
            extra['stack_candidates'] = r['stack_candidates']
        out.append(emit_row(secname, label, extra, m, z))

    # (b2) the 3 NON-BINDING even-m next-depth lifecycle rows (m=14/16/18,
    #      z=3m+14 stick + NEW birth), contingent on the kit-16 even-m
    #      lifecycle chain (z=3m+12 measured 3/3 EXACT).
    K14_EVENLIFE = json.loads(K17_EVENLIFE_JSON)
    for r in K14_EVENLIFE:
        m = r['m']
        z = r['z']
        extra = {'co_token_%d_allowed' % m: True,
                 's_domain': '{%d..%d}' % (m, max(m + 38, z + 2)), 'arity_max': 3,
                 'style': 'x0 published residual-band style',
                 'registered_by': ('kit-16 frozen future_slice_registration_constants even-m '
                                   'lifecycle continuation proposal (commit f997daca), contingent '
                                   'on the kit-16 even-m lifecycle outcomes (z=3m+12 3/3 '
                                   'EXACT); the next-depth rows (stick z=3m+14 of {m,2m+14} '
                                   '+ NEW {m,2m+16}) are the registered kit-17 candidates; '
                                   'NON-BINDING scaffold row'),
                 'candidate': r['cand'],
                 'seat_kind': 'even-m lifecycle next-depth',
                 'expect_seats': r['seats'],
                 'expect_dead_seat': r['dead_seat'],
                 'binding': False}
        if r.get('trio'):
            extra['trio_tracker_z'] = r['trio']
        if r.get('stack_candidates'):
            extra['stack_candidates'] = r['stack_candidates']
        secname = 'evenlife_m%d_z%d_row_record' % (m, z)
        label = 'probe_evenlifecycle_next_m%d_z%d' % (m, z)
        out.append(emit_row(secname, label, extra, m, z))

    # (b3) the WINDOW SWEEPS m=47 z in {85..92}, m=48 z in {86..93}
    #      (kit-16 frozen window proposals; register-before-measure
    #      satisfied by this freeze).
    for z in range(85, 93):
        out.append(emit_row(
            'inband_m47_z%d_row_record' % z,
            'inband_window_m47_z%d' % z,
            {'co_token_47_allowed': True,
             's_domain': '{47..%d}' % max(47 + 38, z + 2), 'arity_max': 3,
             'style': 'x0 published residual-band style',
             'registered_by': 'kit-16 frozen output section future_slice_registration_constants window proposal (commit f997daca), rows z in {85..92} = z*(47)-8..-1; register-before-measure satisfied by this freeze; m=47 is NOT strip-covered',
             'candidate': '0 separations each (in-band-clean precedent); FIRST-EVER below-frontier m=47 rows, no strip-derivation claim made',
             'band': 'm=47 window pinning: z in {85..92} here + frontier {93} (kit-16); z in {25..84} remains unmeasured, unregistered'},
            47, z))

    for z in range(86, 94):
        out.append(emit_row(
            'inband_m48_z%d_row_record' % z,
            'inband_window_m48_z%d' % z,
            {'co_token_48_allowed': True,
             's_domain': '{48..%d}' % max(48 + 38, z + 2), 'arity_max': 3,
             'style': 'x0 published residual-band style',
             'registered_by': 'kit-16 frozen output section future_slice_registration_constants window proposal (commit f997daca), rows z in {86..93} = z*(48)-8..-1; register-before-measure satisfied by this freeze; m=48 is NOT strip-covered',
             'candidate': '0 separations each (in-band-clean precedent); FIRST-EVER below-frontier m=48 rows, no strip-derivation claim made',
             'band': 'm=48 window pinning: z in {86..93} here + frontier {94} (kit-16); z in {25..85} remains unmeasured, unregistered'},
            48, z))

    # (c) future-slice registration constants for kit-18 (engine-free,
    #     NOT measured here).
    out.append({'section': 'future_slice_registration_constants',
                'label': 'engine_free_paper_only_K0832_closed_form_next_slice_predictions_NOT_measured_here',
                'registered_for_next_execution_kit_log_S5': [[
                    json.loads(K18_FUTURE_JSON)
                ]]})

    # (h) published anchor rechecks (1,210 spots, verbatim published values:
    #     the 1,027 kit-16 anchors byte-carried + the 183 kit-16 published
    #     census separation spots first-anchored here).
    rechecks = []
    H.cache_clear()
    for (R, X, z2, expected, role) in K17_ANCHORS:
        XX = tuple(sorted(X, reverse=True))
        hv = H(R, XX, z2)
        S = sum(X)
        ev = v(S, z2, R)
        rechecks.append({'R': R, 'X': list(XX), 'z': z2, 'value': hv,
                         'collapse': ev, 'published_value': expected,
                         'match': hv == expected,
                         'conform': hv == ev,
                         'role': role})
    out.append({'section': 'published_anchor_rechecks',
                'label': 'one_thousand_two_hundred_ten_published_spots_reproduce_exactly_match_field_is_value_equality_with_published',
                'rows': rechecks,
                'note': 'the separation spots are separations by construction (value != collapse BY DESIGN); the match criterion is equality with the PUBLISHED value'})

    res = {'result': 'EXPLORE-DONE', 'sections': out}
    print(json.dumps(res, sort_keys=True, separators=(',', ':')))


if __name__ == '__main__':
    main()
